powerpagecomponent.content:
{"copy":"<div class="demo demo-native"><p class="demo-kicker">Approach / 01</p><h1>Out of the box</h1><p class="demo-lead">A native Power Pages list. Actions, views, search and permissions come from exported metadata.</p><nav class="demo-pathways" aria-label="Implementation"><a href="/approach/out-of-the-box/" aria-current="page">Out of the box</a><a href="/approach/web-api/">Web API</a><a href="/approach/pcf/">PCF</a></nav>{{ snippets['Demo/Access guidance'] }}{{ snippets['Demo/Native guidance'] }}<p data-native-row-count aria-live="polite"></p>{% include 'entity_list' key: 'b4700000-0000-4000-8000-7194d58d3aa1' %}</div>","hiddenfromsitemap":false,"isroot":false,"pagetemplateid":"b4700000-0000-4000-8000-2546863c3d7d","parentpageid":"b4700000-0000-4000-8000-602c5631122a","partialurl":"out-of-the-box","publishingstateid":"b4700000-0000-4000-8000-73c49e548d0c","rootwebpageid":"b4700000-0000-4000-8000-2887756c2bd6","sharedpageconfiguration":false,"title":"Out of the box","customcss":"/* Preserve the native Power Pages list, form, lookups and modal behavior. */
.demo-native .entitylist,.demo-native .entity-form,.demo-native .crmEntityFormView{background:#fff;border:1px solid var(--demo-border);padding:24px;border-radius:5px}.demo-native .entity-grid .view-toolbar{border:0;margin-bottom:20px}.demo-native .entity-grid .view-toolbar .view-select{font-weight:600}.demo-native .btn-primary,.demo-native input[type=submit]{background:var(--demo-forest);border-color:var(--demo-forest);color:white;border-radius:4px;padding:10px 18px}.demo-native .crmEntityFormView .tab-title{font-size:22px}.demo-native .crmEntityFormView .section-title{font-size:17px;padding:14px 0;margin-bottom:16px}.demo-native .crmEntityFormView table.section{border-spacing:18px 12px;border-collapse:separate}.demo-native .crmEntityFormView table.section td.cell{padding:10px 0}.demo-native .crmEntityFormView .control input,.demo-native .crmEntityFormView .control select{min-height:43px}.demo-native .entity-grid table td{padding:16px 12px}
.demo-native [data-native-row-count],.demo-native .demo-description-count{font-size:12px;color:var(--demo-muted);margin:10px 0}
","customjavascript":"(function(){'use strict';const label=document.querySelector('[data-native-row-count]');if(!label)return;const list=document.querySelector('.entitylist');if(!list)return;const update=()=>{const count=list.querySelectorAll('tbody tr[data-id]').length;const text=count+' accounts on this page';if(label.textContent!==text)label.textContent=text;};new MutationObserver(update).observe(list,{childList:true,subtree:true});update();})();
"}
